use vstd::prelude::*;

verus! {

fn is_sorted(arr: &Vec<i32>) -> (result: bool)
    requires
        arr.len() > 0,
    ensures
        result == (forall|i: int, j: int| 0 <= i < j < arr.len() ==> (arr[i] <= arr[j])),
{
    // Initialize a variable to track the sorted status
    let mut sorted = true;

    // Iterate through the array to check the sorting condition
    let n = arr.len() as int;
    assert(n > 0); // Ensure the array is non-empty

    // Loop invariant: sorted holds true if all checked pairs are in nondecreasing order
    // We will check pairs (i, i + 1) for all valid i
    let mut i = 0;
    while i < n - 1
        decreases n - 1 - i
    {
        // Check the current pair
        if arr[i] > arr[i + 1] {
            sorted = false; // Found a pair that violates the nondecreasing order
        }
        i = i + 1; // Move to the next index
    }

    // Return the result based on the sorted status
    result = sorted;
}
}